<?php require_once 'includes/functions.php';$u=login_required();if($u['role']==='patient'){$s=db()->prepare('SELECT r.*,d.name AS other_name,d.blood_group AS other_bg FROM blood_requests r JOIN users d ON d.user_id=r.donor_id WHERE r.patient_id=? ORDER BY r.created_at DESC');}else{$s=db()->prepare('SELECT r.*,p.name AS other_name,p.blood_group AS other_bg FROM blood_requests r JOIN users p ON p.user_id=r.patient_id WHERE r.donor_id=? ORDER BY r.created_at DESC');}$s->execute([$u['user_id']]);$rs=$s->fetchAll();$title='Dashboard';require 'includes/header.php';?><h1>Hello, <?=e($u['name'])?></h1><p><?=e($u['role'])?> · <?=e($u['blood_group'])?> · <?=e($u['location'])?></p><?php if($u['role']==='patient'):?><p><a class="btn" href="search.php">Find donors</a></p><?php endif;?><section class="panel"><h2><?=$u['role']==='patient'?'Your requests':'Requests to you'?></h2><div class="tablewrap"><table><tr><th>ID</th><th><?= $u['role']==='patient'?'Donor':'Patient'?></th><th>Hospital</th><th>Status</th><th>Action</th></tr><?php foreach($rs as $r):?><tr><td>#<?=(int)$r['request_id']?></td><td><?=e($r['other_name'])?> (<?=e($r['other_bg'])?>)</td><td><?=e($r['hospital'])?></td><td><?=e(str_replace('_',' ',$r['status']))?></td><td><?php if($u['role']==='donor'&&$r['status']==='Pending'):?><form method="post" action="action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['request_id']?>"><button name="action" value="accept">Accept</button> <button name="action" value="reject">Reject</button></form><?php elseif($u['role']==='donor'&&$r['status']==='Accepted'):?><form method="post" action="action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['request_id']?>"><button name="action" value="donated">Mark donated</button></form><?php elseif($u['role']==='patient'&&$r['status']==='Donation_Marked'):?><a href="confirm.php?id=<?=(int)$r['request_id']?>">Confirm donation</a><?php elseif($u['role']==='patient'&&$r['status']==='Confirmed'):?><a href="review.php?id=<?=(int)$r['request_id']?>">Rate/review</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>